let sdkPromise;
function vimeoSdk(){if(window.Vimeo)return Promise.resolve(window.Vimeo);if(sdkPromise)return sdkPromise;sdkPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');const timer=setTimeout(()=>reject(new Error('Vimeo не ответил')),12000);script.src='https://player.vimeo.com/api/player.js';script.onload=()=>{clearTimeout(timer);window.Vimeo?resolve(window.Vimeo):reject(new Error('Плеер недоступен'));};script.onerror=()=>{clearTimeout(timer);reject(new Error('Не удалось подключить Vimeo'));};document.head.append(script);}).catch(error=>{sdkPromise=null;throw error;});return sdkPromise;}
function frameFor(video,{muted=false,controls=true,title='Видеоролик'}={}){const frame=document.createElement('iframe'),url=new URL(video.embedUrl);url.searchParams.set('autoplay','1');url.searchParams.set('playsinline','1');if(video.provider==='vimeo'){url.searchParams.set('muted',muted?'1':'0');url.searchParams.set('controls',controls?'1':'0');url.searchParams.set('title','0');url.searchParams.set('byline','0');url.searchParams.set('portrait','0');url.searchParams.set('loop','0');url.searchParams.set('dnt','1');}else{url.searchParams.set('mute',muted?'1':'0');url.searchParams.set('rel','0');}frame.src=url.toString();frame.title=title;frame.allow='autoplay; fullscreen; picture-in-picture; encrypted-media';frame.allowFullscreen=true;return frame;}
